function signalCodes(start, goal, codes) {
  const oneApart = (a, b) => { let d = 0; for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) d++; return d === 1; };
  let best = 0;
  const used = new Set([start]);
  const visit = (word, length) => {
    if (word === goal) { if (!best || length < best) best = length; return; }
    for (const code of codes) {
      if (used.has(code) || !oneApart(word, code)) continue;
      used.add(code);
      visit(code, length + 1);
      used.delete(code);
    }
  };
  visit(start, 1);
  return best;
}

function signalCodes(start, goal, codes) {
  const unused = new Set(codes);
  if (!unused.has(goal)) return 0;
  unused.delete(start);
  let layer = [start];
  for (let length = 1; layer.length; length++) {
    const next = [];
    for (const word of layer) {
      for (let i = 0; i < word.length; i++) {
        for (let c = 97; c <= 122; c++) {
          const candidate = word.slice(0, i) + String.fromCharCode(c) + word.slice(i + 1);
          if (!unused.has(candidate)) continue;
          if (candidate === goal) return length + 1;
          unused.delete(candidate);
          next.push(candidate);
        }
      }
    }
    layer = next;
  }
  return 0;
}
